package com.tekwatt.reservation.dto;import com.tekwatt.reservation.entity.*;import java.time.Instant;import java.util.UUID;public record ReservationResponse(UUID id,UUID tenantId,UUID userId,UUID chargerId,UUID connectorId,String reference,ReservationStatus status,Instant startsAt,Instant expiresAt,Instant createdAt,Instant updatedAt){public static ReservationResponse from(Reservation r){return new ReservationResponse(r.getId(),r.getTenantId(),r.getUserId(),r.getChargerId(),r.getConnectorId(),r.getReference(),r.getStatus(),r.getStartsAt(),r.getExpiresAt(),r.getCreatedAt(),r.getUpdatedAt());}}
